/// 在系统默认浏览器打开外部链接(回复正文里的 http/https 链接)。
#[cfg_attr(feature = "desktop", tauri::command)]
pub fn open_url(url: String) -> Result<(), String> {
    let u = url.trim();
    if !(u.starts_with("http://") || u.starts_with("https://")) {
        return Err("仅允许打开 http/https 链接".into());
    }
    #[cfg(target_os = "windows")]
    {
        // rundll32 不解析 &,URL 原样透传(cmd start 会在 & 处截断)
        Command::new("rundll32")
            .args(["url.dll,FileProtocolHandler", u])
            .spawn()
            .map_err(|e| e.to_string())?;
    }
    #[cfg(target_os = "macos")]
    {
        Command::new("open")
            .arg(u)
            .spawn()
            .map_err(|e| e.to_string())?;
    }
    #[cfg(all(unix, not(target_os = "macos")))]
    {
        Command::new("xdg-open")
            .arg(u)
            .spawn()
            .map_err(|e| e.to_string())?;
    }
    Ok(())
}
use super::{translate::Translator, protocol::{Event, TurnStatus}};
use super::super::stream::Mailbox;
use crate::chat::ChatStreamEvent;
use std::{collections::VecDeque, sync::Arc, time::{Duration, Instant}};
pub(super) const SUPERVISOR_EXITED: &str = "AgentdSupervisorExited";
pub struct Route {
    pub req: String,
    pub session: String,
    pub active: Arc<parking_lot::Mutex<std::collections::HashMap<String, String>>>,
    pub acknowledged: bool,
    pub started: bool,
    pub reservation: (Arc<parking_lot::Mutex<std::collections::HashSet<String>>>, String),
    pub turn: Option<String>,
    pub translator: Translator,
    pub stream: Arc<Mailbox>,
    pub registered_at: Instant,
    pub last_event_at: Instant,
    pub idle_timeout: Duration,
    pub max_duration: Duration,
    pub abort_deadline: Option<Instant>,
    pub pending: VecDeque<ChatStreamEvent>,
    pub terminal: Option<(Option<ChatStreamEvent>, ChatStreamEvent)>,
    pub first_error: Option<String>,
}
impl Route {
    pub fn accept(&mut self, turn: String, event: Event) -> anyhow::Result<()> {
        if self.terminal.is_some() || self.stream.is_finished() { return Ok(()); }
        if !self.started {
            anyhow::ensure!(matches!(event, Event::Started), "AgentdTurnOrder: expected turn.started");
            self.started = true;
            if self.turn.is_none() { self.turn = Some(turn.clone()); }
        }
        anyhow::ensure!(self.turn.as_deref() == Some(&turn), "AgentdTurnMismatch");
        self.last_event_at = Instant::now();
        let fatal = matches!(event, Event::Error { .. } | Event::Completed { .. });
        let events = self.translator.accept(event);
        if fatal && self.first_error.is_none() {
            self.first_error = events.iter().find(|e| e.kind == "error").and_then(|e| e.text.clone());
        }
        self.enqueue(events);
        Ok(())
    }
    pub fn timeout_error(&self, now: Instant) -> Option<&'static str> {
        if self.terminal.is_some() || self.stream.is_finished() { return None; }
        if !self.max_duration.is_zero() && now.duration_since(self.registered_at) >= self.max_duration {
            return Some("AgentdTurnMaxTimeout");
        }
        if now.duration_since(self.last_event_at) >= self.idle_timeout {
            return Some("AgentdTurnIdleTimeout");
        }
        None
    }
    pub fn tick(&mut self) {
        if self.terminal.is_none() { let events = self.translator.tick(); self.enqueue(events); }
    }
    fn enqueue(&mut self, events: Vec<ChatStreamEvent>) {
        for event in events {
            if event.kind == "done" { self.terminal = Some((None, event)); }
            else { self.pending.push_back(event); }
        }
    }
    pub fn fail(&mut self, message: &str) {
        if self.stream.is_finished() { return; }
        self.acknowledged = true;
        let error = if self.first_error.is_some() {
            eprintln!("{}", serde_json::json!({"component":"agent.backend", "backend":"pi",
                "reqId":self.req, "phase":"secondary-error", "error":message, "firstError":self.first_error}));
            None
        } else {
            self.first_error = Some(message.into());
            Some(self.translator.make("error", Some(message.into())))
        };
        if let Some((existing, _)) = &mut self.terminal {
            if existing.is_none() { *existing = error; }
            return;
        }
        let events = self.translator.flush();
        self.enqueue(events);
        self.terminal = Some((error, self.translator.make("done", None)));
    }
    pub fn aborted(&mut self) {
        if self.terminal.is_none() {
            let events = self.translator.accept(Event::Completed { status: TurnStatus::Aborted });
            self.enqueue(events);
        }
    }
    pub fn drain(&mut self) -> bool {
        while let Some(event) = self.pending.pop_front() {
            if let Err(event) = self.stream.try_push(event) {
                self.pending.push_front(event);
                return false;
            }
        }
        if self.acknowledged {
            if let Some((error, done)) = self.terminal.take() {
                eprintln!("{}", serde_json::json!({"component":"agent.backend", "backend":"pi",
                    "reqId":self.req, "conversationId":done.conversation_id, "sessionId":self.session,
                    "phase":"done", "error":error.is_some()}));
                self.reservation.0.lock().remove(&self.reservation.1);
                self.active.lock().remove(&self.req);
                self.stream.finish(error, done);
            }
        }
        true
    }
}

impl Drop for Route {
    fn drop(&mut self) {
        self.reservation.0.lock().remove(&self.reservation.1);
        self.active.lock().remove(&self.req);
        // Reserved terminal slots bypass backpressure, even during unwinding.
        if !self.stream.is_finished() {
            self.stream.finish(
                Some(self.translator.make("error", Some(SUPERVISOR_EXITED.into()))),
                self.translator.make("done", None),
            );
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use super::super::super::config::Agentd;
    fn route() -> (Route, super::super::super::EventStream) {
        let (stream, receiver) = Mailbox::channel(4, 4096);
        let active = Arc::new(parking_lot::Mutex::new(std::collections::HashMap::from([("r".into(), "s".into())])));
        let reservations = Arc::new(parking_lot::Mutex::new(std::collections::HashSet::from(["s".into()])));
        (Route { req: "r".into(), session: "s".into(), active, acknowledged: true, started: false,
            reservation: (reservations, "s".into()), turn: None,
            translator: Translator::new("r".into(), None, "/tmp".into(), &Agentd::default()), stream,
            registered_at: Instant::now(), last_event_at: Instant::now(),
            idle_timeout: Duration::from_secs(240), max_duration: Duration::ZERO,
            abort_deadline: None, pending: VecDeque::new(), terminal: None, first_error: None }, receiver)
    }
    #[test]
    fn dropping_undrained_route_releases_active_and_reservation() {
        let (route, _receiver) = route();
        let active = route.active.clone();
        let reservations = route.reservation.0.clone();
        drop(route);
        assert!(active.lock().is_empty());
        assert!(reservations.lock().is_empty());
    }
    #[test]
    fn drop_finishes_full_unacknowledged_mailbox_and_preserves_finished_stream() -> anyhow::Result<()> {
        for finished in [false, true] {
            let (mut route, receiver) = route();
            route.acknowledged = false;
            for _ in 0..4 {
                assert!(route.stream.try_push(route.translator.make("tool", None)).is_ok());
            }
            if finished {
                route.stream.finish(None, route.translator.make("done", None));
            } else {
                route.fail("undrained failure");
            }
            drop(route);
            let wait = Duration::from_secs(1);
            for _ in 0..4 { assert_eq!(receiver.recv_timeout(wait)?.kind, "tool"); }
            if !finished {
                let error = receiver.recv_timeout(wait)?;
                assert_eq!(error.kind, "error");
                assert_eq!(error.text.as_deref(), Some(SUPERVISOR_EXITED));
            }
            assert_eq!(receiver.recv_timeout(wait)?.kind, "done");
            let closed = receiver.recv_timeout(wait).err().ok_or_else(|| anyhow::anyhow!("duplicate terminal"))?;
            assert!(matches!(closed.downcast_ref(), Some(super::super::super::stream::StreamError::Closed)));
        }
        Ok(())
    }
    #[test]
    fn first_failure_survives_abort_timeout() {
        for daemon_event in [false, true] {
            let (mut route, receiver) = route();
            if daemon_event {
                route.accept("t".into(), Event::Started).unwrap();
                route.accept("t".into(), Event::Error { code: "MODEL_ERROR".into(), message: "original".into() }).unwrap();
                route.accept("t".into(), Event::Completed { status: TurnStatus::Error }).unwrap();
            } else { route.fail("MODEL_ERROR: original"); }
            route.aborted();
            route.fail("AgentdAbortTimeout");
            assert!(route.drain());
            let error = receiver.recv_timeout(std::time::Duration::from_secs(1)).unwrap();
            assert_eq!(error.kind, "error");
            assert_eq!(error.text.as_deref(), Some("MODEL_ERROR: original"));
            assert_eq!(receiver.recv_timeout(std::time::Duration::from_secs(1)).unwrap().kind, "done");
        }
    }
    #[test]
    fn idle_budget_starts_at_registration_and_resets_on_hidden_events() -> anyhow::Result<()> {
        let (mut route, _receiver) = route();
        let idle = Duration::from_millis(300);
        route.idle_timeout = idle;
        let before_event = Instant::now() - idle * 5;
        route.registered_at = before_event;
        route.last_event_at = before_event;
        assert_eq!(route.timeout_error(Instant::now()), Some("AgentdTurnIdleTimeout"));
        route.accept("t".into(), Event::Started)?;
        route.accept("t".into(), Event::Reasoning { text: "working".into() })?;
        let last_event = route.last_event_at;
        assert_eq!(route.timeout_error(last_event + idle - Duration::from_millis(1)), None);
        assert_eq!(route.timeout_error(last_event + idle), Some("AgentdTurnIdleTimeout"));
        route.max_duration = idle * 2;
        assert_eq!(route.timeout_error(last_event), Some("AgentdTurnMaxTimeout"));
        route.accept("t".into(), Event::Completed { status: TurnStatus::Completed })?;
        assert_eq!(route.timeout_error(last_event + idle * 10), None);
        Ok(())
    }
}

/// 受控远程执行端点(B 方案)。刻意**不**并进 /api/invoke:
/// invoke 的闸是「命令在不在分发表」,exec 的闸是「总开关+模式+白名单」,
/// 两套语义混一个入口迟早互相漏。闸门顺序与理由见 exec.rs 头注释。
async fn exec_ep(
    State(state): State<ApiState>,
    headers: HeaderMap,
    Json(req): Json<crate::exec::ExecRequest>,
) -> Response {
    let gate = OriginGate::closed();
    // 闸 2:fail-closed。没设访问口令且没强制登录 = 基础面免口令(合成 owner),
    // 那对 exec 就是**无鉴权 shell**。这里直接拒,且不提供开关绕过。
    // 注:这里刻意**不**走「内网免口令」(OriginGate::closed()),exec 必须拿到真凭据 ——
    // 内网免口令是为了让家用 NAS 用户能进对话/知识库,不是为了给局域网开一个无鉴权 shell。
    if effective_token(&state.auth_token).is_none() && !require_login_env() {
        crate::collab::db::audit(
            "anonymous",
            "exec.denied",
            &req.cmd,
            "开放模式(未设访问口令)",
        );
        return (
            StatusCode::FORBIDDEN,
            Json(json!({"error":"本机未设访问口令,远程执行已禁用。请给容器设 POLARIS_AUTH_TOKEN(或 POLARIS_REQUIRE_LOGIN=1)再用"})),
        )
            .into_response();
    }
    let Some(ctx) = app_ctx(&state, &headers, gate).await else {
        return (
            StatusCode::UNAUTHORIZED,
            Json(json!({"error":"未授权 (口令错误或会话失效)"})),
        )
            .into_response();
    };
    // 闸 3:**按设备**。会话上记着这条请求来自哪台设备,台账上那一排「远程执行:
    // 禁止/每次问/允许」在这里才真的生效。设备码进来的对端默认禁止 —— 拿到码不等于
    // 拿到一个 shell,那要机主在台账上单独点头。本机自己/全局口令不受此闸(device_id 为空)。
    let dev = crate::collab::http::bearer_of(&headers)
        .and_then(|t| crate::collab::auth::check_session_with_device(&t).ok())
        .map(|(_, d)| d)
        .unwrap_or_default();
    if let Err(e) = crate::collab::grants::exec_gate(&dev) {
        crate::collab::db::audit(&ctx.username, "exec.denied", &req.cmd, &e);
        return (StatusCode::FORBIDDEN, Json(json!({ "error": e }))).into_response();
    }
    // 角色闸只对**没有设备契约**的调用方生效:设备码进来的是 visitor,它的权限
    // 完全由上面那道契约闸说了算,再压一道 owner 角色等于把这条路彻底堵死。
    let by_grant = matches!(crate::collab::grants::get(&dev), Ok(Some(g)) if !g.revoked);
    if !by_grant && role_rank(&ctx.role) < 3 {
        crate::collab::db::audit(&ctx.username, "exec.denied", &req.cmd, "角色不足");
        return (
            StatusCode::FORBIDDEN,
            Json(json!({"error":"远程执行需要 owner 权限"})),
        )
            .into_response();
    }
    match crate::exec::run(&ctx.username, req).await {
        // 命令跑完即 200(哪怕退出码非 0)——那是命令的结果,不是接口的错误;
        // 调用方看 exit_code/ok 字段。只有闸门拒绝/启动失败才给非 2xx。
        Ok(r) => Json(r).into_response(),
        Err(e) => {
            // 闸门拒绝是 403(不是 500):调用方据此提示「让主机侧开开关/解锁 Shell」。
            let status = if e.contains("未开启远程执行")
                || e.contains("不在白名单")
                || e.contains("白名单模式")
                || e.contains("元字符")
                || e.contains("不能带路径")
            {
                StatusCode::FORBIDDEN
            } else if e.contains("缺少参数")
                || e.contains("工作目录不存在")
                || e.contains("启动失败")
            {
                StatusCode::BAD_REQUEST
            } else {
                StatusCode::INTERNAL_SERVER_ERROR
            };
            (status, Json(json!({ "error": e }))).into_response()
        }
    }
}

async fn invoke(
    State(state): State<ApiState>,
    peer: Option<ConnectInfo<SocketAddr>>,
    headers: HeaderMap,
    Json(req): Json<InvokeRequest>,
) -> Response {
    let gate = gate_of(&state, peer, &headers);
    let Some(ctx) = app_ctx(&state, &headers, gate).await else {
        return (
            StatusCode::UNAUTHORIZED,
            Json(json!({"error":"未授权 (口令错误或会话失效)"})),
        )
            .into_response();
    };
    if role_rank(&ctx.role) < required_role(&req.cmd) {
        crate::collab::db::audit(&ctx.username, "invoke.denied", &req.cmd, "角色不足");
        return (
            StatusCode::FORBIDDEN,
            Json(json!({"error": format!("权限不足:命令 {} 需要更高角色", req.cmd)})),
        )
            .into_response();
    }
    if ctx.user_id > 0 {
        let operation = crate::collab::interconnect::risk_inventory::HIGH_RISK_OPERATIONS.iter()
            .find(|op| op.entry_points.contains(&req.cmd.as_str())).map(|op| op.id);
        if let Some(operation) = operation {
            let token = bearer_of(&headers).map_or_else(String::new, |token| token);
            let payload = json!({"command":req.cmd,"args":req.args});
            let assertion = headers.get("x-polaris-device-assertion")
                .and_then(|value| value.to_str().ok()).map(String::from);
